import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Account  – Contacts","description":"","frontmatter":{"title":"Account  – Contacts"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/account-contacts.md","filePath":"operations-knowledge-base/presales-support/account-contacts.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/presales-support/account-contacts.md"};function c(r,e,s,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Within the platform’s account system, the primary account has broad management permissions. The contact management feature helps meet the day-to-day management needs of businesses and teams.</p><p>The primary account holder can add new contacts and manage related settings flexibly, which helps improve management efficiency and communication convenience.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Primary account users can access the contact management page through:</p><p>Top-right profile avatar → Account → Contacts</p><p>From this page, users can add contacts and configure email settings.</p><h2 id="_3-operation-guide" tabindex="-1">3. Operation Guide <a class="header-anchor" href="#_3-operation-guide" aria-label="Permalink to &quot;3. Operation Guide&quot;">​</a></h2><h3 id="_1-add-new-contact" tabindex="-1">(1) Add New Contact <a class="header-anchor" href="#_1-add-new-contact" aria-label="Permalink to &quot;(1) Add New Contact&quot;">​</a></h3><h4 id="select-contact" tabindex="-1">Select Contact <a class="header-anchor" href="#select-contact" aria-label="Permalink to &quot;Select Contact&quot;">​</a></h4><p>On the contact management page, click the “Select Contact” dropdown menu and choose “Create New Contact.”</p><h4 id="fill-in-basic-information" tabindex="-1">Fill in Basic Information <a class="header-anchor" href="#fill-in-basic-information" aria-label="Permalink to &quot;Fill in Basic Information&quot;">​</a></h4><ul><li>Enter the contact’s first name and last name.</li><li>If the contact belongs to a company, you may also enter the company name.</li><li>Enter a valid email address to ensure smooth email communication.</li><li>Select the appropriate country code (for example, +1) and enter the correct mobile phone number so the contact can be reached if needed.</li></ul><h4 id="fill-in-address-information" tabindex="-1">Fill in Address Information <a class="header-anchor" href="#fill-in-address-information" aria-label="Permalink to &quot;Fill in Address Information&quot;">​</a></h4><ul><li>Enter the street address in detail. If additional space is needed, continue in the second address line.</li><li>Enter the city, state/province, and ZIP/postal code accurately to ensure the address is correctly recorded.</li><li>Select the country where the contact is located.</li></ul><h4 id="set-email-preferences" tabindex="-1">Set Email Preferences <a class="header-anchor" href="#set-email-preferences" aria-label="Permalink to &quot;Set Email Preferences&quot;">​</a></h4><p>Based on the contact’s needs, select the types of emails they should receive, including:</p><ul><li>General emails</li><li>Billing emails</li><li>Support emails</li><li>Product emails</li><li>Domain emails</li></ul><p>This helps define which categories of emails the contact will receive.</p><h4 id="save-changes" tabindex="-1">Save Changes <a class="header-anchor" href="#save-changes" aria-label="Permalink to &quot;Save Changes&quot;">​</a></h4><p>After completing and confirming all information, click the “Save Changes” button to add the new contact.</p><p>If you do not want to continue, click “Cancel.”</p><h2 id="_4-important-notes" tabindex="-1">4. Important Notes <a class="header-anchor" href="#_4-important-notes" aria-label="Permalink to &quot;4. Important Notes&quot;">​</a></h2><h4 id="information-accuracy" tabindex="-1">Information Accuracy <a class="header-anchor" href="#information-accuracy" aria-label="Permalink to &quot;Information Accuracy&quot;">​</a></h4><p>When entering contact information, please ensure that key details such as the email address are accurate to avoid communication issues or operational errors caused by incorrect information.</p><h4 id="permission-management" tabindex="-1">Permission Management <a class="header-anchor" href="#permission-management" aria-label="Permalink to &quot;Permission Management&quot;">​</a></h4><p>Contact information may contain sensitive details. Users should manage account permissions carefully to prevent unauthorized access or modification.</p><h4 id="regular-maintenance" tabindex="-1">Regular Maintenance <a class="header-anchor" href="#regular-maintenance" aria-label="Permalink to &quot;Regular Maintenance&quot;">​</a></h4><p>It is recommended to review and update contact information regularly, remove outdated contacts, and add new ones as needed to keep the contact list accurate and useful.</p><p>Through the contact management feature, the platform provides users with an efficient contact information management system, helping them maintain contact resources more easily, improve communication efficiency, and enhance the overall account management experience.</p>',30)])])}const p=a(i,[["render",c]]);export{u as __pageData,p as default};
